import{_ as a,C as n,o as t,c as r,a2 as i,b as l,w as o,a as d,E as c,a3 as p}from"./chunks/framework.CZqXuAiL.js";const f=JSON.parse('{"title":"Installation","description":"Install NitroCord, the Velocity 4.1.0 fork with built-in attack prevention — Java 25, the Linux kernel firewall, license activation, verification and uninstall.","frontmatter":{"title":"Installation","description":"Install NitroCord, the Velocity 4.1.0 fork with built-in attack prevention — Java 25, the Linux kernel firewall, license activation, verification and uninstall."},"headers":[],"relativePath":"nitrocord/getting-started/installation.md","filePath":"nitrocord/getting-started/installation.md","lastUpdated":1785394104000}'),h={name:"nitrocord/getting-started/installation.md"};function u(g,e,k,y,b,m){const s=n("Mermaid");return t(),r("div",null,[e[1]||(e[1]=i(`<h1 id="installation" tabindex="-1">Installation <a class="header-anchor" href="#installation" aria-label="Permalink to &quot;Installation&quot;">​</a></h1><p>NitroCord is a drop-in replacement for the Velocity proxy jar. You download one file, start it once to generate the configuration files, enter your license key and restart. The whole process takes a few minutes.</p><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><h3 id="java-25-or-newer" tabindex="-1">Java 25 or newer <a class="header-anchor" href="#java-25-or-newer" aria-label="Permalink to &quot;Java 25 or newer&quot;">​</a></h3><p>The NitroCord jar is built for Java 25 and refuses to start on an older JVM. Check what you have:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -version</span></span></code></pre></div><p>The first line must report version 25 or higher, for example:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>openjdk version &quot;25.0.1&quot; 2025-10-21</span></span></code></pre></div><p>If your distribution does not ship Java 25 yet, download a build from <a href="https://adoptium.net/" target="_blank" rel="noreferrer">Adoptium</a> or your JDK vendor of choice.</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><p>NitroCord is developed and supported on Linux. The kernel-level firewall — the component that drops hostile IPs in iptables before they ever reach the proxy — requires:</p><ul><li>a Linux host,</li><li>the <code>ipset</code> and <code>iptables</code> binaries installed,</li><li>the proxy process running as <strong>root</strong> (or with equivalent firewall privileges).</li></ul><div class="tip custom-block"><p class="custom-block-title">No root? You still get protection</p><p>Without root, ipset or iptables, NitroCord logs one warning at startup and falls back to its <strong>in-memory firewall</strong>. Every protection feature still works; bans are simply enforced in userspace instead of the kernel. Nothing else to configure — <code>firewall.ipset</code> degrades gracefully on its own.</p></div><h3 id="optional-extras" tabindex="-1">Optional extras <a class="header-anchor" href="#optional-extras" aria-label="Permalink to &quot;Optional extras&quot;">​</a></h3><p>These are not required for installation, but unlock optional features later:</p><ul><li><strong>MaxMind license key</strong> — enables GeoLite2 country blocking (<code>[country]</code> in <code>protection.toml</code>). Get a free key at <a href="https://www.maxmind.com/en/geolite2/signup" target="_blank" rel="noreferrer">maxmind.com/en/geolite2/signup</a>.</li><li><strong>proxycheck.io / IPHub API keys</strong> — enable the online VPN/proxy check chain on top of the built-in blocklists (<code>[antivpn]</code> in <code>protection.toml</code>).</li></ul><h2 id="install-nitrocord" tabindex="-1">Install NitroCord <a class="header-anchor" href="#install-nitrocord" aria-label="Permalink to &quot;Install NitroCord&quot;">​</a></h2><ol><li><p><strong>Download the jar.</strong> After purchase, download <code>NitroCord-&lt;version&gt;-all.jar</code> from the <a href="https://altis.host" target="_blank" rel="noreferrer">Altis dashboard</a> or the store page you bought from.</p></li><li><p><strong>Place it in your server directory</strong> — the directory where your current Velocity jar (and <code>velocity.toml</code>) lives. NitroCord reuses your existing Velocity configuration, backends and plugins as-is.</p></li><li><p><strong>Start the proxy once:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">java</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -jar</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NitroCord-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">versio</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-all.jar</span></span></code></pre></div><p>On first boot NitroCord generates three files next to each other:</p><table tabindex="0"><thead><tr><th>File</th><th>Contents</th></tr></thead><tbody><tr><td><code>velocity.toml</code></td><td>Standard Velocity configuration (bind, servers, forwarding)</td></tr><tr><td><code>nitrocord.toml</code></td><td>Branding, theme colors, every message, your license key</td></tr><tr><td><code>protection.toml</code></td><td>Every attack-prevention knob</td></tr></tbody></table></li><li><p><strong>Enter your license key.</strong> Open <code>nitrocord.toml</code> and paste the key from the Altis dashboard:</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">license-key = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;PL-XXXX-XXXX-XXXX-XXXX&quot;</span></span></code></pre></div><p>A key is required — without one the proxy refuses to start. See <a href="/pingless-studios-docs/nitrocord/getting-started/licensing">Licensing</a>.</p></li><li><p><strong>Restart the proxy.</strong> Protection services only start when a valid license is present, so this restart is what activates them.</p></li><li><p><strong>Watch the console.</strong> A successful activation shows:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>License verified - thank you for supporting NitroCord.</span></span>
<span class="line"><span>Kernel firewall active: dropping sources of ipset &#39;nitrocord-firewall&#39; in iptables.</span></span></code></pre></div></li></ol>`,18)),(t(),l(p,null,{default:o(()=>[c(s,{id:"mermaid-151",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%22java%20-jar%20NitroCord-%26lt%3Bversion%26gt%3B-all.jar%22%5D%20--%3E%20B%7B%22First%20boot%3F%22%7D%0A%20%20%20%20B%20--%3E%7C%22yes%22%7C%20C%5B%22Generates%20velocity.toml%2C%3Cbr%2F%3Enitrocord.toml%2C%20protection.toml%22%5D%0A%20%20%20%20C%20--%3E%20D%5B%22Enter%20license-key%3Cbr%2F%3Ein%20nitrocord.toml%22%5D%0A%20%20%20%20D%20--%3E%20E%5B%22Restart%22%5D%0A%20%20%20%20B%20--%3E%7C%22no%22%7C%20E%0A%20%20%20%20E%20--%3E%20F%7B%22License%20key%20set%3F%22%7D%0A%20%20%20%20F%20--%3E%7C%22valid%22%7C%20G%5B%22Protection%20engine%20starts%3Cbr%2F%3E%2B%20kernel%20firewall%22%5D%0A%20%20%20%20F%20--%3E%7C%22empty%20%2F%20invalid%22%7C%20H%5B%22Community%20mode%3A%3Cbr%2F%3Evanilla%20Velocity%20behavior%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=i(`<h2 id="post-install-verification-checklist" tabindex="-1">Post-install verification checklist <a class="header-anchor" href="#post-install-verification-checklist" aria-label="Permalink to &quot;Post-install verification checklist&quot;">​</a></h2><p>Run through this once after the restart:</p><ul><li><p><strong>License line</strong> — the console shows <code>License verified - thank you for supporting NitroCord.</code> (it appears a few seconds after the bind, the check runs in the background).</p></li><li><p><strong>Firewall line</strong> — the console shows <code>Kernel firewall active: dropping sources of ipset &#39;nitrocord-firewall&#39; in iptables.</code> when running as root with ipset available.</p></li><li><p><strong>Kernel set exists</strong> — <code>sudo ipset list nitrocord-firewall</code> lists the set (empty is fine; entries appear as bans happen).</p></li><li><p><strong>Bootstrap banner</strong> — the themed <code>attack prevention is now active.</code> line confirms the NitroCord bootstrap ran (it only prints when a license key is configured).</p></li><li><p><strong>Admin command works</strong> — from the proxy console or in-game with the <code>nitrocord.admin</code> permission:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>/nitrocord stats</span></span></code></pre></div><p>You get live counters: total pings, pings per second, total connections, connections per second, blocked connections, firewalled addresses.</p></li><li><p><strong>Server list brand</strong> — ping the proxy from a Minecraft client&#39;s server list; the version brand shows <code>NitroCord</code>.</p></li></ul><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td><code>Address already in use</code> at startup</td><td>Another process holds the bind port</td><td>Change <code>bind</code> in <code>velocity.toml</code> (default <code>0.0.0.0:25565</code>) or stop the conflicting process</td></tr><tr><td><code>License Not Found - set license-key in nitrocord.toml ... The server will now stop.</code></td><td>License key missing</td><td>Paste your key from the Altis dashboard into <code>nitrocord.toml</code>, start again</td></tr><tr><td><code>NitroCord could not verify a license (...) Shutting down.</code></td><td>Key invalid, or license server unreachable with no grace cache</td><td>Re-check the key for typos/truncation, confirm it in your Altis dashboard; check outbound network access to <code>license.altis.host</code></td></tr><tr><td><code>Could not create the &#39;nitrocord-firewall&#39; ipset ...</code></td><td><code>ipset</code>/<code>iptables</code> missing or not running as root</td><td>Install both packages and run the proxy as root — or do nothing and accept the in-memory firewall</td></tr><tr><td>GeoLite2 database download fails</td><td>Wrong MaxMind key or no outbound network access</td><td>Verify <code>country.maxmind-license-key</code>, check the host can reach MaxMind, look at the logged download error</td></tr><tr><td>Bedrock (Geyser) players kicked by nickname/account checks</td><td>Bedrock exemption needs Floodgate/Geyser detected</td><td><code>compat.geyser</code> is <code>true</code> by default — make sure Floodgate (or Geyser) is actually installed as a proxy plugin</td></tr><tr><td>Proxy starts on macOS/Windows, firewall warning logged</td><td>Kernel firewall is Linux-only</td><td>Expected; the in-memory firewall covers bans. Run on Linux for kernel drops</td></tr></tbody></table><h2 id="uninstall" tabindex="-1">Uninstall <a class="header-anchor" href="#uninstall" aria-label="Permalink to &quot;Uninstall&quot;">​</a></h2><p>NitroCord never touches your Velocity plugins or worlds, so removal is clean:</p><ol><li><p><strong>Stop the proxy.</strong></p></li><li><p><strong>Remove the kernel firewall leftovers</strong> (only if the kernel firewall was active). NitroCord intentionally leaves the ipset and its iptables rule in place on shutdown so remaining entries expire on their own — remove them manually:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iptables</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -D</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> INPUT</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> set</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --match-set</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nitrocord-firewall</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -j</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DROP</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ipset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> destroy</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> nitrocord-firewall</span></span></code></pre></div></li><li><p><strong>Delete the NitroCord files</strong> from the server directory:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>NitroCord-&lt;version&gt;-all.jar</span></span>
<span class="line"><span>nitrocord.toml</span></span>
<span class="line"><span>protection.toml</span></span>
<span class="line"><span>nitrocord/            # data directory: license cache, verified-IP whitelist, anti-VPN cache</span></span></code></pre></div></li><li><p><strong>Put a Velocity jar back</strong> and start it. Your <code>velocity.toml</code>, forwarding secret, plugins and their configurations carry over unchanged.</p></li></ol><div class="warning custom-block"><p class="custom-block-title">Keep nitrocord.toml if you might come back</p><p><code>nitrocord.toml</code> contains your license key, and <code>nitrocord/whitelist.txt</code> inside the data directory holds up to 30 days of verified player IPs that bypass attack-mode checks. Back both up if there is any chance you reinstall — losing the whitelist means every player re-verifies after the next attack.</p></div>`,9))])}const C=a(h,[["render",u]]);export{f as __pageData,C as default};
